const crcTable=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;crcTable[n]=c>>>0;}
export function crc32(bytes){let crc=0xffffffff;for(const byte of bytes)crc=crcTable[(crc^byte)&255]^(crc>>>8);return (crc^0xffffffff)>>>0;}
function buffer(size){const bytes=new Uint8Array(size);return {bytes,view:new DataView(bytes.buffer)};}
export async function zipFiles(files,onProgress=()=>{}){if(!files.length)throw new Error('No hay imágenes para descargar.');if(files.length>65535)throw new Error('El lote supera el límite del ZIP.');const parts=[],central=[];let offset=0,centralSize=0;const enc=new TextEncoder(),now=new Date(),year=Math.max(1980,Math.min(2107,now.getFullYear())),date=((year-1980)<<9)|((now.getMonth()+1)<<5)|now.getDate(),time=(now.getHours()<<11)|(now.getMinutes()<<5)|(now.getSeconds()>>1);
for(let i=0;i<files.length;i++){const file=files[i],name=enc.encode(file.name),size=file.size;if(size>0xffffffff||offset+size+30+name.length>0xffffffff)throw new Error('El ZIP supera 4 GB. Exportá menos fotos por lote.');const bytes=new Uint8Array(await file.arrayBuffer()),crc=crc32(bytes),local=buffer(30+name.length),l=local.view;l.setUint32(0,0x04034b50,true);l.setUint16(4,20,true);l.setUint16(6,0x0800,true);l.setUint16(10,time,true);l.setUint16(12,date,true);l.setUint32(14,crc,true);l.setUint32(18,size,true);l.setUint32(22,size,true);l.setUint16(26,name.length,true);local.bytes.set(name,30);parts.push(local.bytes,file);
const entry=buffer(46+name.length),c=entry.view;c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x0800,true);c.setUint16(12,time,true);c.setUint16(14,date,true);c.setUint32(16,crc,true);c.setUint32(20,size,true);c.setUint32(24,size,true);c.setUint16(28,name.length,true);c.setUint32(42,offset,true);entry.bytes.set(name,46);central.push(entry.bytes);centralSize+=entry.bytes.length;offset+=local.bytes.length+size;onProgress(i+1,files.length);await new Promise(r=>setTimeout(r,0));}
const end=buffer(22),e=end.view;e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,centralSize,true);e.setUint32(16,offset,true);return new Blob([...parts,...central,end.bytes],{type:'application/zip'});}
